#!/usr/bin/env bash
set -uo pipefail
REPO_DIR="${CARE_ASD_REPO_DIR:-$HOME/Dung_TDTU/CARE_ASD}"; DATA_ROOT="${CARE_ASD_DATA_ROOT:-$HOME/Dung_TDTU/data/CARE_ASD}"; cd "$REPO_DIR"; export CUBLAS_WORKSPACE_CONFIG=:4096:8
RUN_ID="server02_phase9_gated_fusion_$(date -u +%Y%m%dT%H%M%SZ)"; NEAR_CACHE="$(find "$DATA_ROOT/official_vector_cache" -mindepth 2 -maxdepth 2 -name cache.json -printf '%T@ %h\n' | sort -nr | head -n1 | cut -d' ' -f2-)"; RESIDUAL_CACHE="$(find "$DATA_ROOT/care_residual_vector_cache" -mindepth 2 -maxdepth 2 -name cache.json -printf '%T@ %h\n' | sort -nr | head -n1 | cut -d' ' -f2-)"; NEURAL_CACHE="$(find "$DATA_ROOT/neural_cache" -mindepth 2 -maxdepth 2 -name cache.json -printf '%T@ %h\n' | sort -nr | head -n1 | cut -d' ' -f2-)"; B00="$(find reports/alignment -path '*server02_phase6_alignment*' -name scores.csv -printf '%T@ %p\n' | sort -nr | head -n1 | cut -d' ' -f2-)"; REL_DIR="$DATA_ROOT/reliability_index/$RUN_ID"; REPORT_DIR="reports/fusion/$RUN_ID"; CHECKPOINT_DIR="$DATA_ROOT/checkpoints/gated_fusion/$RUN_ID"; LOG_DIR="outputs/fusion/$RUN_ID"; SERVER_REPORT="reports/server/$RUN_ID.md"; mkdir -p "$DATA_ROOT/reliability_index" "$CHECKPOINT_DIR" "$LOG_DIR" reports/fusion reports/server
LOG_PATH="$LOG_DIR/gated_fusion.log"; TASK_STATUS=0; uv run --extra official-alignment care-asd data build-reliability-index --neural-cache-dir "$NEURAL_CACHE" --output-dir "$REL_DIR" --workers 16 >>"$LOG_PATH" 2>&1 || TASK_STATUS=$?; if [ "$TASK_STATUS" -eq 0 ]; then uv run --extra official-alignment care-asd gated-fusion-dev --near-cache-dir "$NEAR_CACHE" --residual-cache-dir "$RESIDUAL_CACHE" --reliability-index "$REL_DIR/reliability.parquet" --output-dir "$REPORT_DIR" --checkpoint-dir "$CHECKPOINT_DIR" --config configs/experiment/phase9_gated_fusion.yaml >>"$LOG_PATH" 2>&1 || TASK_STATUS=$?; fi; if [ "$TASK_STATUS" -eq 0 ]; then uv run --extra official-alignment care-asd mvp-bootstrap --reference-scores "$B00" --candidate-scores "$REPORT_DIR/scores.csv" --output "$REPORT_DIR/paired_bootstrap_b02_vs_b00.json" --iterations 5000 --seed 2026 >>"$LOG_PATH" 2>&1 || TASK_STATUS=$?; fi
printf 'gated_fusion=%s\n' "$TASK_STATUS" >"$LOG_DIR/status.txt"; { printf '# Phase 9 gated fusion report\n\nrun_id=%s\nnear_cache=%s\nresidual_cache=%s\nreliability=%s\ntask_status=%s\n\n```text\n' "$RUN_ID" "$NEAR_CACHE" "$RESIDUAL_CACHE" "$REL_DIR" "$TASK_STATUS"; tail -n 80 "$LOG_PATH" 2>/dev/null || true; printf '\n```\n'; } >"$SERVER_REPORT"; LD_LIBRARY_PATH="" git add "$SERVER_REPORT"; [ -d "$REPORT_DIR" ] && LD_LIBRARY_PATH="" git add "$REPORT_DIR"; LD_LIBRARY_PATH="" git commit -m "report: add $RUN_ID"; LD_LIBRARY_PATH="" git pull --rebase origin main; LD_LIBRARY_PATH="" git push origin main; printf 'run_id=%s task_status=%s\n' "$RUN_ID" "$TASK_STATUS"; exit "$TASK_STATUS"
